<?php
namespace App\Services;
use App\Models\{User,Task,Attendance,WeeklyConsolidatedItem,PerformanceRegister};
use Illuminate\Support\{Carbon,Collection};
use Illuminate\Support\Facades\Validator;
class BrandsDashboard {
 public function build(array $filters,User $actor):array {
  $v=Validator::make($filters,['tab'=>'nullable|in:productivity,people,perfect_store,activation,visibility,workstream','period'=>'nullable|in:week,month,year','date'=>'nullable|date_format:Y-m-d','owner'=>'nullable|integer|min:1','cohort'=>'nullable|in:internal,unilever,off_trade,activations','partner'=>'nullable|in:castel,unilever','q'=>'nullable|string|max:150','sort'=>'nullable|in:newest,oldest,title,owner','page'=>'nullable|integer|min:1','per_page'=>'nullable|integer|min:5|max:50','table_filters'=>'nullable|json|max:12000'])->validate();
  $v['table_filters']=Validator::make(['tables'=>json_decode($v['table_filters']??'{}',true)],['tables'=>'array|max:12','tables.*'=>'array:column,q,sort,direction,page','tables.*.column'=>'nullable|string|max:80','tables.*.q'=>'nullable|string|max:150','tables.*.sort'=>'nullable|string|max:80','tables.*.direction'=>'nullable|in:asc,desc','tables.*.page'=>'nullable|integer|min:1'])->validate()['tables'];
  $tab=$v['tab']??'productivity';$period=$v['period']??'week';$anchor=Carbon::parse($v['date']??today());
  $from=match($period){'month'=>$anchor->copy()->startOfMonth(),'year'=>$anchor->copy()->startOfYear(),default=>$anchor->copy()->startOfWeek()};$to=match($period){'month'=>$from->copy()->endOfMonth(),'year'=>$from->copy()->endOfYear(),default=>$from->copy()->endOfWeek()};
  $aliases=User::departmentAliases('brands_marketing');
  $weekly=WeeklyConsolidatedItem::with('leadStaff','creator')->whereIn('department',$aliases)->whereDate('week_start','<=',$to)->whereDate('week_end','>=',$from)->when($period!=='week',fn($q)=>$q->whereDate('week_start','>=',$from))->get();
  if(!BrandsReports::manager($actor))$weekly=$weekly->reject(fn($w)=>in_array($w->report_status,['draft','submitted','returned'],true))->values();
  $registers=PerformanceRegister::whereIn('department',$aliases)->whereNotNull('approved_at')->whereDate('period_start','<=',$to)->whereDate('period_end','>=',$from)->when($period!=='week',fn($q)=>$q->whereDate('period_start','>=',$from))->get();
  $historyIds=$from->lt(now()->startOfWeek())?$weekly->pluck('lead_staff_id')->merge($weekly->pluck('created_by'))->merge($weekly->flatMap(fn($w)=>$w->supporting_staff_ids??[]))->merge($registers->pluck('owner_id')):collect();
  $staff=User::internalStaff()->whereIn('department',$aliases)->orderBy('name')->get()->filter(fn($u)=>$u->isActive()||($u->status==='suspended'&&$historyIds->contains($u->id)))->values();
  $names=User::internalStaff()->pluck('name','id');$owner=$v['owner']??null;
  $matches=function($row)use($v,$owner){return (!$owner||(int)$row['owner_id']===(int)$owner||in_array((int)$owner,array_map('intval',$row['data']['collaborators']??[]),true))&&(empty($v['q'])||str_contains(mb_strtolower(strip_tags($row['title'].' '.json_encode($row['data']))),mb_strtolower($v['q'])));};
  $reports=app(BrandsReports::class);$rows=$weekly->toBase()->map(fn($w)=>$reports->payload($w,'weekly')+['id'=>$w->id,'source_type'=>'weekly','source_token'=>BrandsReports::token($w),'is_draft'=>in_array($w->report_status,['draft','submitted','returned'],true),'source_label'=>in_array($w->report_status,['draft','submitted','returned'],true)?'Draft · Not published':($w->report_status==='reviewed'?((int)$w->report_submitted_by===(int)$w->report_reviewed_by?'Manager published report':'Reviewed report'):'Saved weekly report')])->merge($registers->toBase()->filter(fn($r)=>isset(config('brands_dashboard.schemas')[$r->kind])||$r->kind==='campaign')->map(fn($r)=>$reports->payload($r,'register')+['id'=>$r->id,'source_type'=>'register','source_token'=>BrandsReports::token($r),'source_label'=>$r->kind==='campaign'?'Saved activity':((int)$r->submitted_by===(int)$r->approved_by?'Manager published report':'Reviewed report')]))->filter($matches)->values();
  $rows=$rows->map(fn($row)=>$row+['owner'=>$names[$row['owner_id']]??'Retained staff history','can_edit'=>BrandsReports::member($actor)&&(BrandsReports::manager($actor)||(int)$row['owner_id']===$actor->id)]);
  $tables=[];$summary=[];$notice='';
  $col=fn($key,$label,$format='text')=>compact('key','label','format');
  $base=[$col('week','Reporting Week','date'),$col('title','Activity'),$col('owner','Owner')];
