   $summary=[['Clock-in Hours',$closed->isEmpty()?null:round($closed->sum(fn($a)=>$a->scheduledWorkingMinutes()??0)/60,1),'hours'],['Tasks Assigned',$tasks->count(),'number'],['Tasks Completed',$completed,'number'],['Punctuality Score',$expected?round(100*$punctual/$expected,1):null,'percent'],['Completion Rate',$tasks->count()?round(100*$completed/$tasks->count(),1):null,'percent'],['Productivity Score',count($scores)&&!in_array(null,$scores,true)?round(array_sum($scores)/count($scores),1):null,'percent']];
   $taskRows=$tasks->map(fn($t)=>['id'=>$t->id,'source_type'=>'task','reference'=>'TSK-'.$t->id,'title'=>$t->title,'owner'=>$t->assignee?->name??'Unassigned','collaborators'=>collect($t->supporting_staff_ids??[])->map(fn($id)=>['name'=>$names[$id]??'Retained staff history','responsibility'=>null])->values()->all(),'priority'=>$t->priority,'status'=>$t->isApprovedForPerformance()?'Completed · approved':$t->status,'due'=>$t->due_on?->toDateString(),'week'=>$t->created_at?->toDateString(),'url'=>route('portal.tasks.edit',$t),'can_edit'=>false]);
   $tables[]=$this->table('tasks','Task Tracker',[$col('reference','Task ID'),$col('title','Action'),$col('owner','Owner'),$col('collaborators','Collaborators','people'),$col('priority','Priority'),$col('status','Status'),$col('due','Due Date','date')],$taskRows,$v);
   $definitions=collect(config('department_kpis.brands_marketing',[]))->map(fn($d)=>['title'=>$d['name'],'definition'=>$d['definition'],'unit'=>$d['unit']==='GHS'?'GH₵':$d['unit'],'source'=>$d['source']]);
   $tables[]=$this->table('definitions','KPI Measurement Guide',[$col('title','KPI'),$col('definition','Measurement'),$col('unit','Unit'),$col('source','Evidence Source')],$definitions,array_replace($v,['sort'=>'title']));
   $notice='Hours use completed clock-in sessions and deduct the existing break allowance. Open sessions are not treated as completed workdays. Completion uses approved tasks. Productivity follows the existing 10% punctuality, 65% delivery and 25% KPI calculation; incomplete scores remain unmeasured.';
  }elseif($tab==='people'){
   $people=$rows->where('category','people')->map($flatten)->map(fn($r)=>array_merge($r,['scope_label'=>$this->scopeLabel($r),'cohort_label'=>config('brands_dashboard.schemas.people.cohort.options.'.$r['cohort'],$r['cohort']),'attrition_rate'=>!empty($r['planned_count'])&&isset($r['attrition_count'])?round(100*$r['attrition_count']/$r['planned_count'],1):null]));
   if(!empty($v['cohort']))$people=$people->where('cohort',$v['cohort']);
   $tables[]=$this->table('people','People & Team Coverage',array_merge($base,[$col('scope_label','Scope'),$col('planned_count','Planned','number'),$col('active_count','Active','number'),$col('attrition_count','Attrition','number'),$col('attrition_rate','Attrition Rate','percent'),$col('leave_count','Leave','number'),$col('absent_count','Absent','number'),$col('notes','Updates','rich')]),$people,$v);
   $notice='Choose a People group to view its scopes. Attrition rate is attrition divided by planned headcount × 100. Missing or zero planned headcount remains unmeasured. Month and year views retain each weekly snapshot.';
  }elseif($tab==='perfect_store'){
   $partner=$v['partner']??'castel';$perfect=$rows->where('category','perfect_store')->filter(fn($r)=>($r['data']['partner']??null)===$partner);
   $metrics=$partner==='castel'?['coverage'=>'Coverage','osa'=>'OSA','innovation'=>'Innovation','perfect_store'=>'Perfect Store']:['coverage'=>'Coverage','osa'=>'OSA','must_have'=>'Must Have','npd'=>'NPD','perfect_store'=>'Perfect Store'];
   $previousRows=PerformanceRegister::whereIn('department',$aliases)->whereNotNull('approved_at')->whereIn('kind',['perfect_store','campaign'])->whereDate('period_start','>=',$from->copy()->subWeek())->whereDate('period_start','<=',$to)->orderByDesc('approved_at')->orderByDesc('id')->get()->map(fn($record)=>$reports->payload($record,'register'));
   $previousKey=fn($r,$week)=>$r['owner_id'].'|'.($r['data']['partner']??'').'|'.($r['data']['breakdown']??'overall').'|'.mb_strtolower(trim($r['data']['location']??'')).'|'.$week;
   $previousIndex=[];foreach($previousRows as $previous){$key=$previousKey($previous,Carbon::parse($previous['week'])->startOfWeek()->toDateString());if(!isset($previousIndex[$key]))$previousIndex[$key]=$previous['data'];}
   $metricRows=collect();foreach($perfect as $r)foreach($metrics as $key=>$label)if(collect(['target','previous','actual'])->contains(fn($p)=>isset($r['data'][$key.'_'.$p.'_percent']))){$data=$r['data'];$priorWeek=Carbon::parse($r['week'])->startOfWeek()->subWeek()->toDateString();$previous=$data[$key.'_previous_percent']??($previousIndex[$previousKey($r,$priorWeek)][$key.'_actual_percent']??null);$actual=$data[$key.'_actual_percent']??null;$metricRows->push($r+['metric'=>$label,'location'=>$data['location']??'Overall','breakdown'=>ucfirst($data['breakdown']??'overall'),'target'=>$data[$key.'_target_percent']??null,'previous'=>$previous,'actual'=>$actual,'change'=>$previous!==null&&$actual!==null?round($actual-$previous,1):null]);}
   $groups=$partner==='castel'?['outlet'=>'Outlet Results']:['region'=>'Regional Summary','distributor'=>'Distributor Summary'];
   foreach(['overall'=>'Overall Results']+$groups as $key=>$heading){
    $columns=[$col('week','Reporting Week','date'),$col('owner','Owner')];
    if($key!=='overall')$columns[]=$col('location',match($key){'outlet'=>'Outlet','region'=>'Region','distributor'=>'Distributor'});
    $tables[]=$this->table($key==='overall'?'perfect':'perfect_'.$key,ucfirst($partner).' · '.$heading,array_merge($columns,[$col('metric','KPI'),$col('target','Target','percent'),$col('previous','Previous Week','percent'),$col('actual','Current Week','percent'),$col('change','Change (pp)','number')]),$metricRows->filter(fn($r)=>($r['data']['breakdown']??'overall')===$key),$v);
   }
   $other=$metricRows->reject(fn($r)=>in_array($r['data']['breakdown']??'overall',array_merge(['overall'],array_keys($groups)),true));
   if($other->isNotEmpty())$tables[]=$this->table('perfect_other',ucfirst($partner).' · Other Recorded Breakdowns',[$col('week','Reporting Week','date'),$col('owner','Owner'),$col('breakdown','Breakdown'),$col('location','Location'),$col('metric','KPI'),$col('target','Target','percent'),$col('previous','Previous Week','percent'),$col('actual','Current Week','percent'),$col('change','Change (pp)','number')],$other,$v);
   $notice='Previous values use the saved comparison or the prior approved weekly report for the same owner, partner and location. Month and year views list weekly results. Percentages are not added or averaged across outlets, staff or weeks without a recorded denominator. Historical formatted KPI tables remain readable below.';
  }elseif($tab==='activation'){
   $activation=$rows->where('category','activation')->map($flatten);$briefs=$activation->filter(fn($r)=>!empty($r['brief_date']))->unique(fn($r)=>$r['owner_id'].'|'.$r['title'].'|'.($r['partner']??'').'|'.$r['brief_date']);$closed=$briefs->where('brief_status','closed');$decided=$closed->whereIn('outcome',['won','lost']);$won=$decided->where('outcome','won')->count();
   $summary=[['Briefs Received',$briefs->count(),'number'],['Responded',$briefs->whereNotNull('revert_date')->count(),'number'],['Pending',$briefs->whereIn('brief_status',['received','pending'])->count(),'number'],['Closed',$closed->count(),'number'],['Success Rate',$decided->count()?round(100*$won/$decided->count(),1):null,'percent']];
   $tables[]=$this->table('briefs','Briefs Tracker',array_merge([$col('id','ID')],$base,[$col('partner','Partner'),$col('client','Client / Requester'),$col('brief_date','Brief Date','date'),$col('revert_date','Revert Date','date'),$col('brief_status','Status'),$col('remarks','Remark','rich')]),$activation,$v);
   $kpis=$activation->map(fn($r)=>$r+['sales_achieved'=>!empty($r['target_sales'])&&isset($r['total_sales'])?round(100*$r['total_sales']/$r['target_sales'],1):null,'reach_achieved'=>!empty($r['target_reach'])&&isset($r['total_reach'])?round(100*$r['total_reach']/$r['target_reach'],1):null,'conversion_percent'=>!empty($r['conversion_base'])&&isset($r['conversions'])?round(100*$r['conversions']/$r['conversion_base'],1):null]);
   $tables[]=$this->table('activation_kpis','Activity KPIs',array_merge($base,[$col('partner','Partner'),$col('sales_unit','Sales Unit'),$col('target_sales','Target Sales','number'),$col('total_sales','Total Sales','number'),$col('sales_achieved','Sales Achieved','percent'),$col('target_reach','Target Reach','number'),$col('total_reach','Total Reach','number'),$col('reach_achieved','Reach Achieved','percent'),$col('conversion_percent','Conversion','percent'),$col('mechanic','Brief / Mechanic','rich')]),$kpis,$v);
   $notice='Success rate uses won briefs divided by closed briefs with a recorded won/lost outcome. Conversion uses the recorded eligible audience / interactions. Each result belongs to its reporting week; missing figures are not zero.';
  }elseif($tab==='visibility'){
   $visibility=$rows->where('category','visibility')->map($flatten)->map(fn($r)=>$r+['gap'=>isset($r['scheduled'],$r['deployed'])?$r['scheduled']-$r['deployed']:null]);
   $tables[]=$this->table('visibility','Visibility Tracker',array_merge($base,[$col('posm_type','POSM Type'),$col('partner','Partner'),$col('planned_scope','Planned Scope','number'),$col('active_scope','Active Scope','number'),$col('scheduled','Total Scheduled','number'),$col('deployed','Total Deployed','number'),$col('gap','Gap to Go','number'),$col('status','Status'),$col('notes','Update','rich')]),$visibility,$v);
   $movements=\App\Models\PosmLedger::with('creator')->whereRaw('COALESCE(occurred_on, DATE(created_at)) BETWEEN ? AND ?',[$from->toDateString(),$to->toDateString()])->when($owner,fn($q)=>$q->where('created_by',$owner))->get()->map(fn($m)=>['id'=>$m->id,'week'=>$m->occurred_on?->toDateString()??$m->created_at->toDateString(),'title'=>$m->item_name,'owner'=>$m->creator?->name??'Retained staff history','partner'=>$m->client_brand,'quantity_in'=>$m->quantity_in,'quantity_out'=>$m->quantity_out,'status'=>'Recorded movement']);
   $tables[]=$this->table('movements','POSM Movements',array_merge($base,[$col('partner','Client / Brand'),$col('quantity_in','Quantity In','number'),$col('quantity_out','Quantity Out','number'),$col('status','Status')]),$movements,$v);
   $notice='Gap to Go is scheduled quantity minus deployed quantity. This reporting view does not change warehouse stock balances.';
  }else{
   $work=$rows->where('category','workstream')->map($flatten)->map(fn($r)=>array_replace($r,['collaborator_details'=>collect($r['collaborators']??[])->map(fn($id)=>['name'=>$names[$id]??'Retained staff history','responsibility'=>$r['collaborator_roles'][$id]??''])->values()->all()]));
   $latest=$work->reject(fn($r)=>$r['is_draft']??false)->sortByDesc('week')->unique(fn($r)=>$weekly->firstWhere('id',$r['id'])?->report_series??'entry-'.$r['id']);
   $summary=[['Total Tasks',$latest->count(),'number'],['Tasks Pending',$latest->where('status','!=','Done')->count(),'number'],['Tasks Completed',$latest->where('status','Done')->count(),'number']];
   $tables[]=$this->table('workstream','Task Tracker',[$col('week','Week','date'),$col('project','Project / Workstream'),$col('brand','Brand'),$col('title','Task'),$col('task_in_week','Task in Week','rich'),$col('owner','Owner'),$col('collaborator_details','Collaborators','people'),$col('priority','Priority'),$col('status','Status'),$col('kpis','KPI Commitments','rich'),$col('source_label','Publication')],$work,$v);
   $notice='Weekly reports retain their original reporting dates. Month and year views list the saved weekly entries. Totals use the latest status per linked workstream; reported completion remains separate from verified productivity. Copied drafts are visible to managers only and excluded from published totals. Use View Details and Submit a Correction to complete a copied draft for publication.';
  }
  if(in_array($tab,['people','perfect_store','activation','visibility'])){
   $pattern=match($tab){'people'=>'/people|resource|capability|welfare|training|staff|compensation/i','perfect_store'=>'/perfect\s*store|OSA|merchandis|coverage|shelf|retail/i','activation'=>'/activation|campaign|promotion|back.to.school|vaseline|heineken/i','visibility'=>'/visibility|POSM|branding|shelf|deployment|installation/i'};
   $saved=$rows->where('source_type','weekly')->filter(fn($r)=>preg_match($pattern,strip_tags($r['title'].' '.json_encode($r['data']))))->map(fn($r)=>$r+['project'=>$r['data']['project'],'task_in_week'=>$r['data']['task_in_week'],'kpis'=>$r['data']['kpis']??null]);
   $tables[]=$this->table('saved_reports','Earlier Saved Reports',array_merge($base,[$col('project','Workstream'),$col('task_in_week','Reported Progress','rich'),$col('kpis','KPI Commitments','rich')]),$saved,$v);
  }
  return ['tab'=>$tab,'period'=>['mode'=>$period,'from'=>$from->toDateString(),'to'=>$to->toDateString()],'partner'=>$v['partner']??'castel','cohort'=>$v['cohort']??'','people_groups'=>config('brands_dashboard.schemas.people.cohort.options'),'staff'=>$staff->map(fn($u)=>['id'=>$u->id,'name'=>$u->name,'active'=>$u->isActive(),'photo'=>$u->profilePhotoUrl()]),'tables'=>$tables,'summary'=>$summary,'notice'=>$notice,'can_enter'=>BrandsReports::member($actor),'can_review'=>BrandsReports::manager($actor),'actor'=>$actor->id];
 }
 private function scopeLabel(array $row): string {
  if(!empty($row['scope']))return config('brands_dashboard.schemas.people.scope.options.'.$row['scope'],$row['scope']);
  $scopes=config('brands_dashboard.people_scopes.'.$row['cohort'],[]);
  return count($scopes)===1?reset($scopes):config('brands_dashboard.schemas.people.cohort.options.'.$row['cohort'],'Not recorded');
 }
 private function columnText($value):string {
  if(is_array($value))return collect($value)->map(fn($person)=>is_array($person)?implode(' ',array_filter([$person['name']??null,$person['responsibility']??null])):(string)$person)->join(' ');
  return trim(html_entity_decode(strip_tags(preg_replace('/<[^>]+>/', ' ', (string)$value)),ENT_QUOTES|ENT_HTML5,'UTF-8'));
 }
 private function table(string $id,string $title,array $columns,Collection $rows,array $filters):array {
  $state=$filters['table_filters'][$id]??[];$keys=array_column($columns,'key');$column=in_array($state['column']??'', $keys,true)?$state['column']:'';
  $query=trim($state['q']??'');$available=$rows->count();
  if($query!=='')$rows=$rows->filter(function($row)use($columns,$column,$query){$text=collect($columns)->filter(fn($c)=>!$column||$c['key']===$column)->map(fn($c)=>$this->columnText($row[$c['key']]??null))->join(' ');return str_contains(mb_strtolower($text),mb_strtolower($query));});
  $sort=$filters['sort']??'newest';$rows=match($sort){'title'=>$rows->sortBy('title',SORT_NATURAL|SORT_FLAG_CASE),'owner'=>$rows->sortBy('owner',SORT_NATURAL|SORT_FLAG_CASE),'oldest'=>$rows->sortBy('week'),default=>$rows->sortByDesc(fn($r)=>($r['week']??'').'-'.str_pad((string)($r['id']??0),12,'0',STR_PAD_LEFT))};
  $sortColumn=collect($columns)->firstWhere('key',$state['sort']??'');$direction=$state['direction']??'asc';
  if($sortColumn){$key=$sortColumn['key'];$numeric=in_array($sortColumn['format'],['number','percent']);$rows=$rows->sort(function($a,$b)use($key,$numeric,$direction){$left=$a[$key]??null;$right=$b[$key]??null;if($left===null||$left===''||$right===null||$right===''){return (($left===null||$left==='')?1:0)-(($right===null||$right==='')?1:0);}$result=$numeric?((float)$left<=>(float)$right):strnatcasecmp($this->columnText($left),$this->columnText($right));return $direction==='desc'?-$result:$result;});}
  $per=$filters['per_page']??10;$total=$rows->count();$last=max(1,(int)ceil($total/$per));$page=min((int)($state['page']??$filters['page']??1),$last);
  return ['id'=>$id,'title'=>$title,'columns'=>$columns,'rows'=>$rows->slice(($page-1)*$per,$per)->map(function($row)use($columns){foreach($columns as $column)if($column['format']==='rich')$row[$column['key']]=\App\Support\ReportRichText::html($row[$column['key']]??'');unset($row['data']);return $row;})->values(),'total'=>$total,'available'=>$available,'page'=>$page,'last'=>$last,'filter'=>['column'=>$column,'q'=>$query,'sort'=>$sortColumn['key']??'','direction'=>$direction]];
 }
}
